	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/iam/capabilities", wrapper.ListCapabilities)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/iam/kpi", wrapper.GetKpi)
